# -*- coding: utf-8 -*-
import io
p='tree.html'; s=io.open(p,encoding='utf-8').read()
def R(a,b):
    global s
    assert s.count(a)==1,a[:80]; s=s.replace(a,b)
R('<details class="person s-hyp" id="elvira"><summary><span class="pname">Шутис Эльвира (Иосифовна?)</span><span class="pyrs">1926? – до 1991</span><span class="badge"><i class="dot"></i>кандидат по документам</span></summary><div class="pbody">',
  '<details class="person s-one" id="elvira"><summary><span class="pname">Комарова (Шутисс) Эльвира (Эльвина) Иосифовна</span><span class="pyrs">1925/26 – 1990</span><span class="badge"><i class="dot"></i>один источник + семья</span></summary><div class="pbody">\n        <p><b>Ваганьковское кладбище (30.10.2026).</b> Семья сообщила, что Эльвира, Эвелина и их родители похоронены на Ваганьковском. В базе подписанных захоронений ГБУ «Ритуал» (открытые данные Москвы, поиск E-poisk) на одном участке найдены <b>Комарова Эльвина</b> (в записи годы 1925 и 1990) и <b>Шутисс Софья Васильевна</b> (годы 1908 и 1944). Во всей московской базе фамилия встречается только в написании «Шутисс», с двумя «с», как в военном списке 1946 года. Имя записано как «Эльвина». Это либо её настоящее имя, либо ошибка в надписи или в базе. Год смерти 1990 сходится с тем, что Эльвира умерла до отъезда Софьи в США.</p>\n        <p class="flag">С августа 2026 года сайт по требованию Роскомнадзора не показывает сами записи, только «есть совпадения» или «нет». Поэтому всё выше восстановлено по ответам на запросы с фильтрами (имя, годы, второй человек на участке, кладбище). Какой из двух годов год рождения, а какой — смерти, по таким ответам не отличить. Номер участка узнать не успел: после серии запросов сайт закрыл мне доступ. Отца Иосифа и Эвелину под фамилией Шутисс база не знает. Возможно, на памятнике их нет, или Эвелина записана под фамилией мужа. Проверить всё разом может фото памятника.</p>')
R('<p>Мать Ларисы и Софьи. Сестра — Эвелина Шутис.','<p>Мать Ларисы и Софьи. Сестра — Эвелина Шутис(с). Мать, по данным кладбища, — Софья Васильевна Шутисс.')
R('<p class="flag">Отчество и год рождения Эльвиры семья не знает, поэтому совпадение пока не доказано.','<p class="flag">Раньше это совпадение не было доказано: отчества и года рождения Эльвиры семья не знала. Теперь его подкрепляют данные кладбища: та же редкая фамилия Шутисс, год 1925 или 1926 и Москва.')
R('В «Памяти народа» документов на Эвелину Шутис нет.</p></div></details>',
  'В «Памяти народа» документов на Эвелину Шутис нет. По словам семьи, похоронена на Ваганьковском вместе с сестрой и родителями. В базе кладбищ под фамилией Шутисс её нет, значит, на памятнике она, вероятно, под фамилией мужа.</p></div></details>\n      <details class="person s-one" id="sofyash"><summary><span class="pname">Шутисс Софья Васильевна</span><span class="pyrs">1908? – 1944?</span><span class="badge"><i class="dot"></i>один источник</span></summary><div class="pbody"><p>Вероятная мать Эльвиры и Эвелины, прапрабабушка Насти. Похоронена на Ваганьковском, на одном участке с Комаровой Эльвиной. В базе захоронений с ней связаны годы 1908 и 1944. Скорее всего, она родилась в 1908 году и умерла в 1944-м, во время войны, когда Эльвире было 18–19 лет. Отчество Васильевна русское, так что она могла быть не литовкой: тогда литовец — отец, Иосиф (Юозас). Внучку, Софью Николаевну, вероятно, назвали в её честь.</p><p class="flag">Если она родилась в 1908 году, Эльвину она родила в 17 лет. Это возможно, но годы надо проверить по памятнику или по акту о смерти 1944 года. Такой акт хранится в московском ЗАГСе, а со временем передаётся в ЦГА Москвы.</p><p class="src">E-poisk / открытые данные ГБУ «Ритуал», 30.10.2026 (A-0016) · кладбище — со слов семьи</p></div></details>')
R('<li><b>Прабабушка Эльвира:</b> не Иосифовна ли она, не 1926 ли года рождения? Служила ли в армии в войну? Год смерти и кладбище. <span class="why">В Москве найдена сержант Шутисс Эльвира Иосифовна 1926 года рождения. Если это она, следующий шаг — её отец Иосиф и место рождения.</span></li>',
  '<li><b>Ваганьковское:</b> номер участка или фото памятника Шутиссов и Комаровой. Звали ли прабабушку Эльвирой или Эльвиной? Мама Эльвиры — Софья Васильевна? Как звали отца и под какой фамилией Эвелина. <span class="why">В базе кладбища на одном участке нашлись Шутисс Софья Васильевна (1908, 1944) и Комарова Эльвина (1925, 1990). Памятник даст точные даты, имя отца и фамилию Эвелины.</span></li>')
R('<li><b>Карелина, Фастов, Москва.</b>','<li><b>Эльвира или Эльвина.</b> В базе Ваганьковского кладбища — «Комарова Эльвина», в военном списке 1946 года — «Шутисс Эльвира». Это та же женщина, одно из написаний — ошибка или домашний вариант имени. Фамилия во всех документах пишется с двумя «с»: Шутисс.</li>\n      <li><b>Карелина, Фастов, Москва.</b>')
R('<li><a href="https://pamyat-naroda.ru/heroes/?adv_search=y&amp;last_name=%D0%A8%D1%83%D1%82%D0%B8%D1%81%D1%81&amp;group=all">',
  '<li><a href="https://epoisk.ru/burmsk/">E-poisk — захоронения Москвы</a> (открытые данные ГБУ «Ритуал», записи скрыты): «Шутисс» — только Софья Васильевна (1908, 1944); на её участке Комарова Эльвина (1925, 1990); фильтр «Ваганьковское» — да. Шутис / Шутисс + Иосиф, Эвелина — нет. После серии запросов сайт закрыл доступ.</li>\n        <li>Яндекс-архив: «Шутисс», «Шутис Софья», «Шутис Эльвина», «Шутис Эвелина» — пусто. Попутно: в метрической книге московского костёла Петра и Павла за 1914 год (ЦГА Москвы ф.609 оп.2 д.102 ск.491) крёстным записан Викентий Шутис, крестьянин Поневежского уезда Ковенской губернии. Это доказывает, что литовцы Шутисы жили в Москве ещё до революции, но родство с Эльвирой не установлено.</li>\n        <li><a href="https://pamyat-naroda.ru/heroes/?adv_search=y&amp;last_name=%D0%A8%D1%83%D1%82%D0%B8%D1%81%D1%81&amp;group=all">')
R('    elvira: "Литва (или Латвия) → Москва (если кандидат верен — армия, демобилизация в Москве в 1946)",',
  '    elvira: "Москва: армия, демобилизация 1946; похоронена на Ваганьковском (1990). Корни отца — Литва",\n    sofyash: "Москва; Ваганьковское кладбище",')
io.open(p,'w',encoding='utf-8').write(s)
